await bash("python3 - <<'EOF'
import base64, a85
print('enc sure:', repr(base64.a85encode(b'sure')), repr(a85.encode(b'sure')))
for bad in [b'v', b'a', b'uuuuu']:
    try:
        print(repr(bad), '-> stdlib:', base64.a85decode(bad))
    except Exception as e:
        print(repr(bad), '-> stdlib raises:', type(e).__name__, e)
    try:
        print(repr(bad), '-> ours:', a85.decode(bad))
    except A85Error as e:
        print(repr(bad), '-> ours raises: A85Error', e)
# stdlib overflow message check
try:
    base64.a85decode(b'u'*5 + b'zz')
except Exception as e:
    print('overflow msg:', type(e).__name__, e)
EOF")

await bash("python3 - <<'EOF'
import base64
from a85 import A85Error, decode as d
for bad in [b'v', b'a', b'uuuuu']:
    try:
        print(repr(bad), '-> stdlib:', base64.a85decode(bad))
    except Exception as e:
        print(repr(bad), '-> stdlib raises:', type(e).__name__, ':', e)
    try:
        print(repr(bad), '-> ours:', d(bad))
    except A85Error as e:
        print(repr(bad), '-> ours raises: A85Error :', e)
EOF")
